    ['code' => 'cyber-risk-project', 'prof' => 'cybersecurity-engineer', 'type' => 'situational', 'lvl' => [2, 4], 'diff' => 3, 'sec' => 210, 'skills' => ['risk_compliance', 'stakeholder_management'],
        'fr' => ['Un projet veut ouvrir une base de données clients à un prestataire externe. Comment l\'accompagnez-vous ?', 'Analyse de risques, mesures proportionnées, exigences contractuelles et conformité.',
