    ['code' => 'pentest-report-exec', 'prof' => 'pentester', 'type' => 'technical', 'lvl' => [2, 4], 'diff' => 3, 'sec' => 180, 'skills' => ['communication', 'security_mindset'],
        'fr' => ['Comment présentez-vous les résultats d\'un test d\'intrusion à un comité de direction ?', 'Traduisez la technique en risques métier et en plan d\'action priorisé.',
