    ['code' => 'ciso-budget-pushback', 'prof' => 'ciso', 'type' => 'situational', 'lvl' => [4, 5], 'diff' => 5, 'sec' => 240, 'skills' => ['stakeholder_management', 'negotiation', 'communication'],
        'fr' => ['La direction financière refuse votre budget sécurité. Comment argumentez-vous ?', 'Parlez le langage de la direction : risques chiffrés, scénarios, obligations, options.',
